/* @generated by stategate from sensor.yaml. Do not edit: change the model and run `stategate gen`. */
/* The trace format stategate-view replays. Write the header once, then one
 * record per transition (the HAL's trace hook gives you from, event and to),
 * over any transport: a file, UART, BLE. The viewer refuses a log whose model
 * hash is not the model it has open. */
#ifndef SENSOR_TRACE_H
#define SENSOR_TRACE_H

#include <stddef.h>
#include <stdint.h>
#include <string.h>

/* sha-256 of sensor.yaml, the model this code was generated from. */
static const uint8_t sensor_model_hash[32] = {0x91, 0xed, 0x4e, 0x2c, 0xf8, 0xd0, 0x56, 0x28, 0xee, 0x3b, 0x3f, 0xd6, 0xba, 0x84, 0xa3, 0x6d, 0x26, 0xa3, 0x9c, 0x64, 0xa7, 0xab, 0x2b, 0xd8, 0x21, 0xae, 0xd0, 0x75, 0x7c, 0x40, 0x57, 0x91};

/* Appends one machine's entry to a header: id length, id, model hash. */
static inline size_t sensor_trace_header_entry(uint8_t *out) {
    size_t n = strlen("sensor");
    out[0] = (uint8_t)n;
    memcpy(out + 1, "sensor", n);
    memcpy(out + 1 + n, sensor_model_hash, 32);
    return 1 + n + 32;
}

/* The header of a log from this machine alone. out needs 44 bytes. */
static inline size_t sensor_trace_header(uint8_t *out) {
    memcpy(out, "SGT1", 4);
    out[4] = 1;
    return 5 + sensor_trace_header_entry(out + 5);
}

/* Shared by every machine's trace.h, so a system can include them all. */
#ifndef SG_TRACE_RECORD_SIZE
#define SG_TRACE_RECORD_SIZE 11

static inline void sg_trace_record(uint8_t out[SG_TRACE_RECORD_SIZE], uint32_t t_ms, uint16_t seq, uint8_t machine,
                                   uint8_t instance, uint8_t from, uint8_t event, uint8_t to) {
    out[0] = (uint8_t)t_ms;
    out[1] = (uint8_t)(t_ms >> 8);
    out[2] = (uint8_t)(t_ms >> 16);
    out[3] = (uint8_t)(t_ms >> 24);
    out[4] = (uint8_t)seq;
    out[5] = (uint8_t)(seq >> 8);
    out[6] = machine;
    out[7] = instance;
    out[8] = from;
    out[9] = event;
    out[10] = to;
}
#endif

#endif
